package config

import (
	"encoding/json"
	"fmt"
	"net/url"
	"sort"
	"strings"
	"time"
	"unicode"

	"ferry/internal/domain"
	"ferry/internal/nativeauth"
)

const (
	V2DomainSourceLegacy = "legacy_projection"
	V2DomainSourceNative = "native"
)

func validLogicalModelID(id string) bool {
	if id == "" || strings.TrimSpace(id) != id {
		return false
	}
	for _, r := range id {
		if unicode.IsSpace(r) || unicode.IsControl(r) {
			return false
		}
	}
	return true
}

// maxAutoGeneratedLogicalModelsPerProvider limits only aggregators listed in
// logical_model_policy.json; other providers are unrestricted.
const maxAutoGeneratedLogicalModelsPerProvider = 10

func (f *File) LogicalModelAutoLimit() int {
	if f == nil || f.AutoLogicalModelLimit == nil {
		return maxAutoGeneratedLogicalModelsPerProvider
	}
	return *f.AutoLogicalModelLimit
}

// EnsureSameNameLogicalModels reconciles automatically owned routes and creates
// missing same-name models. Only allowlisted aggregators apply the catalog-size
// limit. Operator-owned logical models and routes remain unchanged.
func EnsureSameNameLogicalModels(f *File) []string {
	if f == nil {
		return nil
	}
	providers := make(map[string]*domain.Provider, len(f.Providers))
	for index := range f.Providers {
		providers[f.Providers[index].ID] = &f.Providers[index]
	}
	type candidate struct {
		providerID string
		enabled    bool
	}
	candidates := map[string]candidate{}
	eligible := map[string]candidate{}
	modelsByProvider := map[string]map[string]bool{}
	order := []string{}
	for _, connection := range f.Connections {
		provider := providers[connection.ProviderID]
		if provider == nil {
			continue
		}
		for _, model := range connection.Models {
			name := model.UpstreamModel
			if !validLogicalModelID(name) {
				continue
			}
			if modelsByProvider[provider.ID] == nil {
				modelsByProvider[provider.ID] = map[string]bool{}
			}
			modelsByProvider[provider.ID][name] = true
			available := provider.Enabled && connection.Enabled
			current, seen := candidates[name]
			if !seen {
				order = append(order, name)
				candidates[name] = candidate{providerID: connection.ProviderID, enabled: available}
			} else if available && !current.enabled {
				candidates[name] = candidate{providerID: connection.ProviderID, enabled: true}
			}
		}
	}
	// Choose an eligible source independently from existing-route reconciliation.
	// An oversized aggregator must not hide a same-name model from a direct
	// provider, regardless of connection order.
	limited := limitedLogicalModelProviders(f)
	for _, connection := range f.Connections {
		provider := providers[connection.ProviderID]
		if provider == nil || (limited[provider.ID] && len(modelsByProvider[provider.ID]) > f.LogicalModelAutoLimit()) {
			continue
		}
		for _, model := range connection.Models {
			if !validLogicalModelID(model.UpstreamModel) {
				continue
			}
			available := provider.Enabled && connection.Enabled
			current, seen := eligible[model.UpstreamModel]
			if !seen || (available && !current.enabled) {
				eligible[model.UpstreamModel] = candidate{providerID: provider.ID, enabled: available}
			}
		}
	}
	reconciled := make([]domain.LogicalModel, 0, len(f.LogicalModels)+len(order))
	existing := make(map[string]bool, len(f.LogicalModels))
	for _, logical := range f.LogicalModels {
		if logical.AutoGenerated {
			selected, supplied := candidates[logical.ID]
			if preferred, ok := eligible[logical.ID]; ok && (preferred.enabled || !selected.enabled) {
				selected = preferred
			}
			if !supplied {
				continue
			}
			logical.DisplayName = logical.ID
			logical.Description = "Automatically created for upstream model " + logical.ID
			logical.Enabled = selected.enabled
			logical.ExistingConversationStrategy = domain.ConversationKeepExisting
			logical.DefaultRoute = domain.RouteSpec{Steps: []domain.RouteStep{{
				ProviderID: selected.providerID, UpstreamModel: logical.ID,
			}}}
		}
		reconciled = append(reconciled, logical)
		existing[logical.ID] = true
	}
	f.LogicalModels = reconciled
	created := make([]string, 0, len(order))
	for _, name := range order {
		if existing[name] {
			continue
		}
		selected, allowed := eligible[name]
		if !allowed {
			continue
		}
		f.LogicalModels = append(f.LogicalModels, domain.LogicalModel{
			ID: name, DisplayName: name, AutoGenerated: true,
			Description:                  "Automatically created for upstream model " + name,
			Enabled:                      selected.enabled,
			ExistingConversationStrategy: domain.ConversationKeepExisting,
			DefaultRoute: domain.RouteSpec{Steps: []domain.RouteStep{{
				ProviderID: selected.providerID, UpstreamModel: name,
			}}},
		})
		existing[name] = true
		created = append(created, name)
	}
	return created
}

// MigrateLegacyV2Domain builds a conservative product-domain projection over
// legacy config. While the source remains legacy_projection it is regenerated
// on every validation, keeping the old Console CRUD facade coherent. Native V2
// drafts set v2_domain_source=native and become authoritative instead.
func MigrateLegacyV2Domain(f *File) (bool, error) {
	if f == nil {
		return false, fmt.Errorf("config must be non-nil")
	}
	if f.V2DomainSource == V2DomainSourceNative {
		return false, nil
	}
	routingPolicies := routingPoliciesForV2Projection(f)
	f.LogicalModels = nil
	f.Providers = nil
	f.Connections = nil
	f.V2MigrationIssues = nil

	for i := range f.Channels {
		channel := &f.Channels[i]
		enabled := channel.EnabledOrDefault()
		provider := domain.Provider{
			ID: channel.ID, Name: channel.ID, Type: providerTypeFromChannel(channel.Type),
			BaseURL: channel.BaseURL, Enabled: enabled,
			Connections: []domain.ConnectionRef{{ID: channel.ID}},
		}
		credential := channel.Credential
		if channel.Type == domain.ChannelCliproxyCodex {
			credential = domain.CredentialRef{SecretRef: domain.OAuthRef(channel.ID)}
		}
		connection := domain.Connection{
			ID: channel.ID, ProviderID: channel.ID, Identity: channel.ID,
			Credential: credential, Enabled: enabled,
		}
		for j := range channel.Models {
			model := &channel.Models[j]
			model.Capabilities = domain.NormalizeProviderModelCapabilities(
				provider.Type, model.Model, model.Protocols, model.Capabilities)
			connection.Models = append(connection.Models, domain.ConnectionModel{
				UpstreamModel: model.Model, Protocols: append([]domain.Protocol(nil), model.Protocols...),
				Capabilities: model.Capabilities, PlanID: model.PlanRef(channel),
				ExecutionTargetID: domain.ResourceTargetID(domain.ChannelTargetID(channel.ID, model.Model)),
			})
		}
		f.Providers = append(f.Providers, provider)
		f.Connections = append(f.Connections, connection)
	}

	for i := range f.Targets {
		target := &f.Targets[i]
		providerID := legacyTargetProviderID(target.ID)
		baseURL := ""
		protocols := []domain.Protocol{}
		if target.Endpoint != nil {
			baseURL = target.Endpoint.BaseURL
			protocols = append(protocols, target.Endpoint.Protocol)
		}
		target.Capabilities = domain.NormalizeProviderModelCapabilities(
			domain.ProviderCustom, target.Model, protocols, target.Capabilities)
		f.Providers = append(f.Providers, domain.Provider{
			ID: providerID, Name: string(target.ID), Type: domain.ProviderCustom,
			BaseURL: baseURL, Enabled: true,
			Connections: []domain.ConnectionRef{{ID: providerID}},
		})
		f.Connections = append(f.Connections, domain.Connection{
			ID: providerID, ProviderID: providerID, Identity: string(target.ID),
			Credential: target.Credential, Enabled: true,
			Models: []domain.ConnectionModel{{
				UpstreamModel: target.Model, Protocols: protocols, Capabilities: target.Capabilities,
				PlanID: target.PlanID, ExecutionTargetID: target.ID,
			}},
		})
	}

	type modelOrigin struct {
		model  domain.LogicalModel
		strict bool
	}
	models := map[string]modelOrigin{}
	for name := range f.Aliases {
		models[name] = modelOrigin{model: domain.LogicalModel{ID: name, DisplayName: name, Enabled: true}}
	}
	for i := range f.Channels {
		channel := &f.Channels[i]
		if !channel.EnabledOrDefault() {
			continue
		}
		for j := range channel.Models {
			name := channel.Models[j].ClientFacing()
			if _, exists := models[name]; !exists {
				models[name] = modelOrigin{model: domain.LogicalModel{ID: name, DisplayName: name, Enabled: true}, strict: true}
			}
		}
	}

	names := make([]string, 0, len(models))
	for name := range models {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		origin := models[name]
		logical := origin.model
		defaultPolicy := findDefaultRoutingPolicy(routingPolicies, name)
		if defaultPolicy == nil {
			logical.Enabled = false
			f.addV2ModelIssue(name, "logical_model", name, "no enabled catch-all route can provide a default route", true)
		} else {
			steps, ok := convertLegacyRoute(f, name, origin.strict, defaultPolicy.Route.Steps)
			if ok {
				logical.DefaultRoute.Steps = steps
			} else {
				logical.Enabled = false
			}
		}
		if len(f.RoutingPolicies) == 0 {
			logical.Overrides = append(logical.Overrides,
				migrateLegacyRuleOverrides(f, logical.ID, defaultPolicy, logical.DefaultRoute)...)
		}
		logical.Overrides = append(logical.Overrides, migrateOverrides(f, routingPolicies, name, origin.strict)...)
		f.LogicalModels = append(f.LogicalModels, logical)
	}
	f.V2DomainSource = V2DomainSourceLegacy
	return true, nil
}

// migrateLegacyRuleOverrides preserves request-context exclusion rules from
// the legacy policy engine when the compatibility document is projected into
// the native product model. This is the bridge used by Low-Code schedules such
// as "12:00-18:00 skip GLM": the default route remains intact and a first-match
// custom-route override removes the scoped legacy tier during the window.
// Target-state predicates remain in the legacy runtime and are reported as
// migration issues because they cannot be evaluated before a V2 route exists.
func migrateLegacyRuleOverrides(f *File, logicalModel string, defaultPolicy *domain.RoutingPolicySpec,
	defaultRoute domain.RouteSpec) []domain.OverrideSpec {
	if defaultPolicy == nil || len(defaultRoute.Steps) != len(defaultPolicy.Route.Steps) {
		return nil
	}
	policyName := f.DefaultPolicy
	legacy, ok := f.Policies[policyName]
	if !ok {
		return nil
	}
	type exclusionGroup struct {
		firstIndex int
		names      []string
		when       domain.RuleWhen
		selectors  []legacyRouteSelector
	}
	groupsByMatch := map[string]*exclusionGroup{}
	groups := []*exclusionGroup{}
	for index, rule := range legacy.Rules {
		if !legacyRuleTouchesRoute(f, rule.When, defaultPolicy, defaultRoute) {
			continue
		}
		if rule.Action.Exclude == nil || !*rule.Action.Exclude {
			if rule.Action.Require != "" || rule.Action.Prefer != nil || rule.Action.Pin != nil || rule.Action.Tier != "" {
				f.addV2ModelIssue(logicalModel, "legacy_rule", rule.Name,
					"legacy ranking/tier action cannot be transferred to native V2 without changing behavior", true)
			}
			continue
		}
		when := rule.When
		if when.Health != "" || when.Cooldown || when.QuotaRemaining != nil ||
			when.QuotaConfidence != "" || when.QuotaMultiplier != nil {
			f.addV2ModelIssue(logicalModel, "legacy_rule", rule.Name,
				"legacy target-state condition cannot be transferred to native V2 without changing behavior", true)
			continue
		}
		if when.Target == "" && when.Pool == "" {
			f.addV2ModelIssue(logicalModel, "legacy_rule", rule.Name,
				"legacy exclusion without a target or pool cannot produce a usable V2 route", true)
			continue
		}
		if when.TimeWindow != nil && when.TimeWindow.Start == when.TimeWindow.End {
			// The legacy half-open matcher treats equal bounds as an empty
			// interval. Do not turn that semantic no-op into an invalid V2 rule.
			continue
		}
		requestWhen := when
		requestWhen.Target, requestWhen.Pool = "", ""
		signature := legacyRequestMatchSignature(requestWhen)
		group := groupsByMatch[signature]
		if group == nil {
			group = &exclusionGroup{
				firstIndex: index, when: requestWhen,
			}
			groupsByMatch[signature] = group
			groups = append(groups, group)
		}
		group.names = append(group.names, rule.Name)
		selector := legacyRouteSelector{pool: when.Pool, target: when.Target}
		if !containsLegacyRouteSelector(group.selectors, selector) {
			group.selectors = append(group.selectors, selector)
		}
	}

	// Legacy exclusion rules compose, whereas native Overrides are first-match.
	// Equal request predicates can be combined safely. Distinct predicates that
	// overlap would require an intersection action, so leave them on the legacy
	// runtime and block native takeover rather than publishing an approximation.
	blocked := map[*exclusionGroup]bool{}
	for left := 0; left < len(groups); left++ {
		for right := left + 1; right < len(groups); right++ {
			if !legacyRequestMatchesOverlap(groups[left].when, groups[right].when) {
				continue
			}
			blocked[groups[left]], blocked[groups[right]] = true, true
			f.addV2ModelIssue(logicalModel, "legacy_rule", strings.Join(groups[right].names, ", "),
				"overlapping legacy exclusion conditions compose multiple actions and cannot be represented by one first-match Override", true)
		}
	}

	out := []domain.OverrideSpec{}
	for _, group := range groups {
		if blocked[group] {
			continue
		}
		route := domain.RouteSpec{}
		removed := false
		for stepIndex, legacyStep := range defaultPolicy.Route.Steps {
			step := defaultRoute.Steps[stepIndex]
			excluded := false
			for _, selector := range group.selectors {
				poolMatches := selector.pool == "" || legacyStep.ChannelGroup == selector.pool ||
					legacyRouteStepMatchesPool(f, step, selector.pool)
				targetMatches := selector.target == "" ||
					legacyRouteStepMatchesTarget(f, step, domain.ResourceTargetID(selector.target))
				if poolMatches && targetMatches {
					excluded = true
					break
				}
			}
			if excluded {
				removed = true
				continue
			}
			route.Steps = append(route.Steps, cloneRouteStep(step))
		}
		if !removed {
			// The rule targets supply outside this logical model and is therefore
			// a semantic no-op for this projection.
			continue
		}
		if len(route.Steps) == 0 {
			f.addV2ModelIssue(logicalModel, "legacy_rule", strings.Join(group.names, ", "),
				"legacy exclusion can intentionally leave no route, which the V2 Override contract cannot represent", true)
			continue
		}
		route.Steps[len(route.Steps)-1].RecoverOn = nil
		window := group.when.TimeWindow
		timezone := ""
		if window != nil || len(group.when.Weekdays) > 0 {
			timezone = legacyTemporalTimezone(legacy.Timezone)
		}
		override := domain.OverrideSpec{
			ID: fmt.Sprintf("legacy-%s-rule-%02d", policyName, group.firstIndex+1), Name: strings.Join(group.names, " + "), Enabled: true,
			Weekdays: normalizeLegacyWeekdays(group.when.Weekdays), Timezone: timezone,
			Window: window, Mode: domain.OverrideCustomRoute, Route: &route,
		}
		if group.when.ConsumerKey != "" {
			override.Callers = []string{group.when.ConsumerKey}
		}
		out = append(out, override)
	}
	return out
}

type legacyRouteSelector struct {
	pool   string
	target string
}

func containsLegacyRouteSelector(selectors []legacyRouteSelector, wanted legacyRouteSelector) bool {
	for _, selector := range selectors {
		if selector == wanted {
			return true
		}
	}
	return false
}

func legacyRuleTouchesRoute(f *File, when domain.RuleWhen, policy *domain.RoutingPolicySpec, route domain.RouteSpec) bool {
	if when.Target == "" && when.Pool == "" {
		return true
	}
	for index, step := range route.Steps {
		legacyStep := policy.Route.Steps[index]
		targetMatches := when.Target == "" || legacyRouteStepMatchesTarget(f, step, domain.ResourceTargetID(when.Target))
		poolMatches := when.Pool == "" || legacyStep.ChannelGroup == when.Pool || legacyRouteStepMatchesPool(f, step, when.Pool)
		if targetMatches && poolMatches {
			return true
		}
	}
	return false
}

func legacyRequestMatchSignature(when domain.RuleWhen) string {
	weekdays := normalizeLegacyWeekdays(when.Weekdays)
	sort.Strings(weekdays)
	raw, _ := json.Marshal(struct {
		ConsumerKey string             `json:"consumer_key,omitempty"`
		Weekdays    []string           `json:"weekdays,omitempty"`
		TimeWindow  *domain.TimeWindow `json:"time_window,omitempty"`
	}{when.ConsumerKey, weekdays, when.TimeWindow})
	return string(raw)
}

func normalizeLegacyWeekdays(values []string) []string {
	out := make([]string, len(values))
	for index, value := range values {
		value = strings.ToLower(value)
		if len(value) >= 3 {
			value = value[:3]
		}
		out[index] = value
	}
	return out
}

func legacyTemporalTimezone(configured string) string {
	if strings.TrimSpace(configured) == "" {
		return "UTC"
	}
	return configured
}

func legacyRequestMatchesOverlap(left, right domain.RuleWhen) bool {
	if left.ConsumerKey != "" && right.ConsumerKey != "" && left.ConsumerKey != right.ConsumerKey {
		return false
	}
	if len(left.Weekdays) > 0 && len(right.Weekdays) > 0 {
		days := map[string]bool{}
		for _, weekday := range normalizeLegacyWeekdays(left.Weekdays) {
			days[weekday] = true
		}
		overlap := false
		for _, weekday := range normalizeLegacyWeekdays(right.Weekdays) {
			overlap = overlap || days[weekday]
		}
		if !overlap {
			return false
		}
	}
	if left.TimeWindow != nil && right.TimeWindow != nil {
		for minute := 0; minute < 24*60; minute++ {
			if legacyWindowMatchesMinute(*left.TimeWindow, minute) && legacyWindowMatchesMinute(*right.TimeWindow, minute) {
				return true
			}
		}
		return false
	}
	return true
}

func legacyWindowMatchesMinute(window domain.TimeWindow, minute int) bool {
	if !validGraphHHMM(window.Start) || !validGraphHHMM(window.End) {
		return false
	}
	parse := func(value string) int {
		return int(value[0]-'0')*600 + int(value[1]-'0')*60 + int(value[3]-'0')*10 + int(value[4]-'0')
	}
	start, end := parse(window.Start), parse(window.End)
	if start <= end {
		return minute >= start && minute < end
	}
	return minute >= start || minute < end
}

func legacyRouteStepMatchesTarget(f *File, step domain.RouteStep, targetID domain.ResourceTargetID) bool {
	for index := range f.Targets {
		target := &f.Targets[index]
		if target.ID == targetID && step.ProviderID == legacyTargetProviderID(target.ID) && step.UpstreamModel == target.Model {
			return true
		}
	}
	for channelIndex := range f.Channels {
		channel := &f.Channels[channelIndex]
		if channel.ID != step.ProviderID {
			continue
		}
		for modelIndex := range channel.Models {
			model := &channel.Models[modelIndex]
			if model.Model == step.UpstreamModel && domain.ResourceTargetID(domain.ChannelTargetID(channel.ID, model.Model)) == targetID {
				return true
			}
		}
	}
	return false
}

func legacyRouteStepMatchesPool(f *File, step domain.RouteStep, poolID string) bool {
	targetIDs := map[domain.ResourceTargetID]bool{}
	for index := range f.Pools {
		if f.Pools[index].ID == poolID {
			for _, targetID := range f.Pools[index].Targets {
				targetIDs[targetID] = true
			}
		}
	}
	for index := range f.Targets {
		target := &f.Targets[index]
		if step.ProviderID == legacyTargetProviderID(target.ID) && step.UpstreamModel == target.Model && targetIDs[target.ID] {
			return true
		}
	}
	for channelIndex := range f.Channels {
		channel := &f.Channels[channelIndex]
		if channel.ID != step.ProviderID {
			continue
		}
		for modelIndex := range channel.Models {
			model := &channel.Models[modelIndex]
			if model.Model != step.UpstreamModel {
				continue
			}
			pools := model.Pools
			if len(pools) == 0 {
				pools = channel.Pools
			}
			for _, candidate := range pools {
				if candidate == poolID {
					return true
				}
			}
			if targetIDs[domain.ResourceTargetID(domain.ChannelTargetID(channel.ID, model.Model))] {
				return true
			}
		}
	}
	return false
}

func cloneRouteStep(step domain.RouteStep) domain.RouteStep {
	if step.RecoverOn != nil {
		step.RecoverOn = append(make([]domain.FailureType, 0, len(step.RecoverOn)), step.RecoverOn...)
	}
	return step
}

func routingPoliciesForV2Projection(f *File) []domain.RoutingPolicySpec {
	if len(f.RoutingPolicies) > 0 {
		return f.RoutingPolicies
	}
	// Derive a route-only view without mutating the legacy runtime. Conditional
	// legacy rules are migrated separately when representable; otherwise they
	// deliberately keep the legacy planner authoritative.
	name, legacy, ok := legacyDefaultPolicy(f)
	if !ok {
		return nil
	}
	spec, err := materializeLegacyRoutingPolicy(name, legacy)
	if err != nil {
		return nil
	}
	return []domain.RoutingPolicySpec{spec}
}

func migrateOverrides(f *File, policies []domain.RoutingPolicySpec, logicalModel string, strict bool) []domain.OverrideSpec {
	out := []domain.OverrideSpec{}
	for _, policy := range policies {
		if !policy.Enabled || isDefaultPolicy(policy.Match) || !policyMatchesModel(policy.Match, logicalModel) {
			continue
		}
		if strings.TrimSpace(policy.Match.Expression) != "" {
			f.addV2ModelIssue(logicalModel, "override", policy.ID,
				"legacy expression conditions are not representable by the Override contract", true)
			continue
		}
		steps, ok := convertLegacyRoute(f, logicalModel, strict, policy.Route.Steps)
		if !ok {
			continue
		}
		required := requirementsFromNames(policy.Match.RequiredCapabilities)
		route := domain.RouteSpec{Steps: steps}
		window := policy.Match.TimeWindow
		if window != nil && window.Start == window.End {
			// Ordered routing policies historically interpret equal bounds as
			// all day. In V2 that is an unconditional temporal predicate.
			window = nil
		}
		timezone := policy.Match.Timezone
		if window != nil || len(policy.Match.Weekdays) > 0 {
			timezone = legacyTemporalTimezone(timezone)
		}
		out = append(out, domain.OverrideSpec{
			ID: policy.ID, Name: policy.Name, Enabled: true,
			Callers:   append([]string(nil), policy.Match.Consumers...),
			Protocols: append([]domain.Protocol(nil), policy.Match.Protocols...),
			Weekdays:  append([]string(nil), policy.Match.Weekdays...), Timezone: timezone,
			Window:   window,
			Required: required, Mode: domain.OverrideCustomRoute, Route: &route,
		})
	}
	return out
}

func findDefaultRoutingPolicy(policies []domain.RoutingPolicySpec, model string) *domain.RoutingPolicySpec {
	for i := range policies {
		policy := &policies[i]
		if policy.Enabled && isDefaultPolicy(policy.Match) && policyMatchesModel(policy.Match, model) {
			return policy
		}
	}
	return nil
}

// Model selection identifies the LogicalModel whose default is being built;
// all other predicates would make the policy conditional and therefore an
// Override. An empty Models list remains the global legacy default.
func isDefaultPolicy(match domain.RoutingPolicyMatch) bool {
	return len(match.Consumers) == 0 && len(match.Protocols) == 0 &&
		len(match.RequiredCapabilities) == 0 && len(match.Weekdays) == 0 &&
		match.TimeWindow == nil && strings.TrimSpace(match.Expression) == ""
}

func policyMatchesModel(match domain.RoutingPolicyMatch, model string) bool {
	if len(match.Models) == 0 {
		return true
	}
	for _, candidate := range match.Models {
		if candidate == model {
			return true
		}
	}
	return false
}

func convertLegacyRoute(f *File, logicalModel string, strict bool,
	legacy []domain.RoutingPolicyStep) ([]domain.RouteStep, bool) {
	out := make([]domain.RouteStep, 0, len(legacy))
	for index, step := range legacy {
		candidates := legacyStepCandidates(f, step, logicalModel, strict)
		if strict && len(candidates) == 0 {
			// A concrete channel-model alias only participates in the legacy
			// groups that actually supply that client-facing model. The legacy
			// planner skips unrelated groups through its model compatibility gate;
			// omitting the same step from the V2 route is behavior-preserving.
			continue
		}
		if len(candidates) != 1 {
			objectID := fmt.Sprintf("%s:step-%d", logicalModel, index+1)
			f.addV2ModelIssue(logicalModel, "route_step", objectID,
				fmt.Sprintf("legacy step resolves to %d Provider+UpstreamModel candidates; explicit migration is required", len(candidates)), true)
			return nil, false
		}
		resolved := candidates[0]
		resolved.RecoverOn = append([]domain.FailureType(nil), step.RecoverOn...)
		out = append(out, resolved)
	}
	if len(out) == 0 {
		f.addV2ModelIssue(logicalModel, "route_step", logicalModel+":route",
			"legacy route has no Provider+UpstreamModel candidate for this logical model", true)
		return nil, false
	}
	// A skipped irrelevant legacy step can turn an originally non-final step
	// into the V2 final step. It has nowhere to advance, so normalize away its
	// inherited progression list after filtering.
	out[len(out)-1].RecoverOn = nil
	return out, true
}

func legacyStepCandidates(f *File, step domain.RoutingPolicyStep, logicalModel string, strict bool) []domain.RouteStep {
	type candidate struct {
		step       domain.RouteStep
		clientName string
	}
	all := []candidate{}
	addChannelModel := func(channel *domain.Channel, model *domain.ChannelModel) {
		all = append(all, candidate{
			step:       domain.RouteStep{ProviderID: channel.ID, UpstreamModel: model.Model},
			clientName: model.ClientFacing(),
		})
	}
	if step.Channel != "" {
		for i := range f.Channels {
			channel := &f.Channels[i]
			if channel.ID != step.Channel {
				continue
			}
			for j := range channel.Models {
				addChannelModel(channel, &channel.Models[j])
			}
		}
	} else {
		poolTargets := map[domain.ResourceTargetID]bool{}
		for i := range f.Pools {
			if f.Pools[i].ID == step.ChannelGroup {
				for _, target := range f.Pools[i].Targets {
					poolTargets[target] = true
				}
			}
		}
		for i := range f.Targets {
			target := &f.Targets[i]
			if poolTargets[target.ID] {
				clientName := target.ModelAlias
				if clientName == "" {
					clientName = target.Model
				}
				all = append(all, candidate{
					step:       domain.RouteStep{ProviderID: legacyTargetProviderID(target.ID), UpstreamModel: target.Model},
					clientName: clientName,
				})
			}
		}
		for i := range f.Channels {
			channel := &f.Channels[i]
			for j := range channel.Models {
				model := &channel.Models[j]
				pools := model.Pools
				if len(pools) == 0 {
					pools = channel.Pools
				}
				inGroup := false
				for _, pool := range pools {
					if pool == step.ChannelGroup {
						inGroup = true
					}
				}
				if poolTargets[domain.ResourceTargetID(domain.ChannelTargetID(channel.ID, model.Model))] {
					inGroup = true
				}
				if inGroup {
					addChannelModel(channel, model)
				}
			}
		}
	}
	seen := map[string]bool{}
	out := []domain.RouteStep{}
	for _, candidate := range all {
		if strict && candidate.clientName != logicalModel {
			continue
		}
		key := domain.ProviderModelKey(candidate.step.ProviderID, candidate.step.UpstreamModel)
		if !seen[key] {
			seen[key] = true
			out = append(out, candidate.step)
		}
	}
	if !strict && len(out) > 1 {
		// An explicit legacy Alias is an abstract capability contract. Inferring
		// one upstream model from a multi-target group would change behavior.
		return out
	}
	return out
}

// OAuthBindingViolations lists every oauth account slot referenced by more
// than one connection. One slot models exactly one upstream subscription
// login: sharing it would double-burn the account's quota and make usage
// displays indistinguishable between providers. Ordinary store:/env:
// secrets stay shareable across connections.
func OAuthBindingViolations(f *File) []string {
	owner := map[string]string{}
	var violations []string
	for i := range f.Connections {
		connection := &f.Connections[i]
		account, oauth := domain.OAuthAccountFromRef(connection.Credential.SecretRef)
		if !oauth {
			continue
		}
		if existing, taken := owner[account]; taken {
			violations = append(violations, fmt.Sprintf(
				"connection %s: oauth account %q is already referenced by connection %s; move that connection to another account before binding this one",
				connection.ID, account, existing))
			continue
		}
		owner[account] = connection.ID
	}
	return violations
}

func ValidateV2Domain(f *File) error {
	if f != nil && (f.LogicalModelAutoLimit() < 0 || f.LogicalModelAutoLimit() > 10000) {
		return fmt.Errorf("auto_logical_model_limit must be between 0 and 10000")
	}
	providers := map[string]*domain.Provider{}
	connections := map[string]*domain.Connection{}
	for i := range f.Providers {
		provider := &f.Providers[i]
		if provider.ID == "" || !nameRe.MatchString(provider.ID) {
			return fmt.Errorf("invalid provider id %q", provider.ID)
		}
		if providers[provider.ID] != nil {
			return fmt.Errorf("duplicate provider id %q", provider.ID)
		}
		if !provider.ModelSyncInterval.Valid() {
			return fmt.Errorf("provider %s: model_sync_interval must be one of off, 30m, or 1h", provider.ID)
		}
		if catalog := provider.ModelSyncCatalog; catalog != nil {
			if provider.Type != domain.ProviderCustom {
				return fmt.Errorf("provider %s: model_sync_catalog is supported only for custom providers", provider.ID)
			}
			if !catalog.Type.Valid() {
				return fmt.Errorf("provider %s: unsupported model_sync_catalog type %q", provider.ID, catalog.Type)
			}
			if !catalog.Plan.Valid() {
				return fmt.Errorf("provider %s: model_sync_catalog plan must be agent or coding", provider.ID)
			}
			if !strings.HasPrefix(catalog.CredentialRef, "store:") || !nameRe.MatchString(strings.TrimPrefix(catalog.CredentialRef, "store:")) {
				return fmt.Errorf("provider %s: model_sync_catalog credential_ref must be a valid store: reference", provider.ID)
			}
		}
		switch provider.Type {
		case domain.ProviderCustom, domain.ProviderCliproxyCodex:
		default:
			return fmt.Errorf("provider %s: unsupported type %q", provider.ID, provider.Type)
		}
		parsed, err := url.Parse(provider.BaseURL)
		if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
			return fmt.Errorf("provider %s: base_url must be an absolute http(s) URL", provider.ID)
		}
		if err := provider.Concurrency.Validate(); err != nil {
			return fmt.Errorf("provider %s: %w", provider.ID, err)
		}
		providers[provider.ID] = provider
		for protocol := range provider.ProtocolConversion {
			if !domain.ValidProtocol(protocol) {
				return fmt.Errorf("provider %s: invalid protocol conversion %q", provider.ID, protocol)
			}
		}
		if provider.Type == domain.ProviderCliproxyCodex {
			provider.ProtocolConversion = provider.EffectiveProtocolConversion()
		}
	}
	for i := range f.Connections {
		connection := &f.Connections[i]
		if connection.ID == "" || !nameRe.MatchString(connection.ID) {
			return fmt.Errorf("invalid connection id %q", connection.ID)
		}
		if connections[connection.ID] != nil {
			return fmt.Errorf("duplicate connection id %q", connection.ID)
		}
		if providers[connection.ProviderID] == nil {
			return fmt.Errorf("connection %s: unknown provider %q", connection.ID, connection.ProviderID)
		}
		if err := connection.Concurrency.Validate(); err != nil {
			return fmt.Errorf("connection %s: %w", connection.ID, err)
		}
		if connection.BaseURL != "" {
			parsed, err := url.Parse(connection.BaseURL)
			if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
				return fmt.Errorf("connection %s: base_url must be an absolute http(s) URL", connection.ID)
			}
		}
		if connection.FullURL != "" {
			parsed, err := url.Parse(connection.FullURL)
			if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" {
				return fmt.Errorf("connection %s: full_url must be an absolute http(s) URL", connection.ID)
			}
		}
		if connection.BaseURL != "" && connection.FullURL != "" {
			return fmt.Errorf("connection %s: base_url and full_url are mutually exclusive", connection.ID)
		}
		if _, oauth := domain.OAuthAccountFromRef(connection.Credential.SecretRef); connection.Credential.SecretRef != "" && !oauth {
			if err := validateSecretRef(connection.Credential.SecretRef); err != nil {
				return fmt.Errorf("connection %s: %w", connection.ID, err)
			}
		}
		if _, _, native := nativeauth.ParseRef(connection.Credential.SecretRef); native {
			if connection.FullURL != "" || connection.Credential.Header != "" || connection.Credential.QueryParam != "" || connection.Credential.Prefix != "" {
				return fmt.Errorf("connection %s: native credential endpoint and placement cannot be overridden", connection.ID)
			}
			base := connection.BaseURL
			if base == "" {
				base = providers[connection.ProviderID].BaseURL
			}
			for _, model := range connection.Models {
				for _, protocol := range model.Protocols {
					if err := nativeauth.ValidateDefaultBinding(connection.Credential.SecretRef, base, string(protocol)); err != nil {
						return fmt.Errorf("connection %s: %w", connection.ID, err)
					}
				}
			}
		}
		connections[connection.ID] = connection
	}
	if !f.startupValidation {
		if violations := OAuthBindingViolations(f); len(violations) > 0 {
			return fmt.Errorf("%s", violations[0])
		}
	}
	for _, provider := range f.Providers {
		seen := map[string]bool{}
		for _, ref := range provider.Connections {
			if seen[ref.ID] {
				return fmt.Errorf("provider %s: duplicate connection ref %q", provider.ID, ref.ID)
			}
			seen[ref.ID] = true
			connection := connections[ref.ID]
			if connection == nil {
				return fmt.Errorf("provider %s: unknown connection %q", provider.ID, ref.ID)
			}
			if connection.ProviderID != provider.ID {
				return fmt.Errorf("provider %s: connection %s belongs to provider %s", provider.ID, ref.ID, connection.ProviderID)
			}
			if provider.ModelSyncCatalog != nil &&
				v2StoreSecretName(connection.Credential.SecretRef) == v2StoreSecretName(provider.ModelSyncCatalog.CredentialRef) {
				return fmt.Errorf("provider %s: model_sync_catalog credential_ref must be separate from connection %s", provider.ID, connection.ID)
			}
		}
	}
	for _, connection := range f.Connections {
		provider := providers[connection.ProviderID]
		found := false
		for _, ref := range provider.Connections {
			found = found || ref.ID == connection.ID
		}
		if !found {
			return fmt.Errorf("connection %s: missing from provider %s connection refs", connection.ID, connection.ProviderID)
		}
	}
	supply := map[string]bool{}
	textSupply := map[string]bool{}
	planIDs := map[string]bool{}
	for _, plan := range f.Plans {
		planIDs[plan.ID] = true
	}
	for connectionIndex := range f.Connections {
		connection := &f.Connections[connectionIndex]
		provider := providers[connection.ProviderID]
		models := map[string]bool{}
		for modelIndex := range connection.Models {
			model := &connection.Models[modelIndex]
			if !validLogicalModelID(model.UpstreamModel) {
				return fmt.Errorf("connection %s: upstream model must be non-empty, trimmed, and contain no whitespace or control characters", connection.ID)
			}
			if models[model.UpstreamModel] {
				return fmt.Errorf("connection %s: duplicate upstream model %q", connection.ID, model.UpstreamModel)
			}
			models[model.UpstreamModel] = true
			providerType := domain.ProviderType("")
			if provider != nil {
				providerType = provider.Type
			}
			if providerType == domain.ProviderCliproxyCodex {
				model.Protocols = []domain.Protocol{domain.CodexModelNativeProtocol(model.UpstreamModel)}
			}
			if len(model.Protocols) == 0 {
				return fmt.Errorf("connection %s model %s: at least one protocol required", connection.ID, model.UpstreamModel)
			}
			for _, protocol := range model.Protocols {
				if !domain.ValidProtocol(protocol) {
					return fmt.Errorf("connection %s model %s: invalid protocol %q", connection.ID, model.UpstreamModel, protocol)
				}
			}
			// Existing configurations predate the dedicated Images bit. Native
			// Images supply is inherent in the declared protocol family.
			model.Capabilities = domain.NormalizeProviderModelCapabilities(
				providerType, model.UpstreamModel, model.Protocols, model.Capabilities)
			if model.PlanID != "" && !planIDs[model.PlanID] {
				return fmt.Errorf("connection %s model %s: unknown plan %q", connection.ID, model.UpstreamModel, model.PlanID)
			}
			key := domain.ProviderModelKey(connection.ProviderID, model.UpstreamModel)
			supply[key] = true
			if model.Capabilities.Text {
				for _, protocol := range model.Protocols {
					switch protocol {
					case domain.ProtocolOpenAIChat, domain.ProtocolOpenAIResponses, domain.ProtocolAnthropic:
						textSupply[key] = true
					}
				}
			}
		}
	}
	for i := range f.Providers {
		provider := &f.Providers[i]
		message := provider.ScheduledMessage
		if message == nil {
			continue
		}
		if len(message.Message) > domain.ProviderScheduledMessageMaxBytes {
			return fmt.Errorf("provider %s: scheduled_message message exceeds %d bytes", provider.ID, domain.ProviderScheduledMessageMaxBytes)
		}
		if !message.Enabled {
			continue
		}
		if strings.TrimSpace(message.Message) == "" {
			return fmt.Errorf("provider %s: scheduled_message message is required when enabled", provider.ID)
		}
		if message.UpstreamModel == "" || strings.TrimSpace(message.UpstreamModel) != message.UpstreamModel {
			return fmt.Errorf("provider %s: scheduled_message upstream_model must be non-empty and trimmed", provider.ID)
		}
		if !textSupply[domain.ProviderModelKey(provider.ID, message.UpstreamModel)] {
			return fmt.Errorf("provider %s: scheduled_message upstream model %q must be supplied by a text-capable connection", provider.ID, message.UpstreamModel)
		}
	}
	EnsureSameNameLogicalModels(f)
	logicalIDs := map[string]bool{}
	for i := range f.LogicalModels {
		logical := &f.LogicalModels[i]
		normalizeFinalV2RouteRecovery(&logical.DefaultRoute)
		for overrideIndex := range logical.Overrides {
			if logical.Overrides[overrideIndex].Route != nil {
				normalizeFinalV2RouteRecovery(logical.Overrides[overrideIndex].Route)
			}
		}
		if strings.TrimSpace(logical.ID) == "" {
			return fmt.Errorf("logical model id required")
		}
		if !validLogicalModelID(logical.ID) {
			return fmt.Errorf("invalid logical model id %q", logical.ID)
		}
		if logicalIDs[logical.ID] {
			return fmt.Errorf("duplicate logical model id %q", logical.ID)
		}
		logicalIDs[logical.ID] = true
		if logical.FirstOutputTimeoutSeconds < 0 || logical.FirstOutputTimeoutSeconds > 7200 {
			return fmt.Errorf("logical model %s: first_output_timeout_seconds must be between 0 and 7200 (0 disables the timeout)", logical.ID)
		}
		if !logical.ExistingConversationStrategy.Valid() {
			return fmt.Errorf("logical model %s: unsupported existing conversation strategy %q",
				logical.ID, logical.ExistingConversationStrategy)
		}
		if logical.Enabled && len(logical.DefaultRoute.Steps) == 0 {
			return fmt.Errorf("logical model %s: enabled model requires a default route", logical.ID)
		}
		if err := validateRouteSupply(logical.ID, logical.DefaultRoute, providers, supply); err != nil {
			return err
		}
		defaultSteps := make(map[string]bool, len(logical.DefaultRoute.Steps))
		for _, step := range logical.DefaultRoute.Steps {
			defaultSteps[domain.ProviderModelKey(step.ProviderID, step.UpstreamModel)] = true
		}
		overrideIDs := map[string]bool{}
		enabledMatchIndexes := map[string]int{}
		catchAllSeen := false
		for overrideIndex, override := range logical.Overrides {
			if override.ID == "" || !nameRe.MatchString(override.ID) || overrideIDs[override.ID] {
				return fmt.Errorf("logical model %s: invalid or duplicate override id %q", logical.ID, override.ID)
			}
			overrideIDs[override.ID] = true
			if err := validateOverrideMatch(logical.ID, override); err != nil {
				return err
			}
			if override.Enabled {
				if catchAllSeen {
					return fmt.Errorf("logical model %s override %s: enabled override follows a catch-all and can never match", logical.ID, override.ID)
				}
				signature := overrideMatchSignature(override)
				if previous, exists := enabledMatchIndexes[signature]; exists {
					return fmt.Errorf("logical model %s override %s: duplicates the match conditions of earlier override %s", logical.ID, override.ID, logical.Overrides[previous].ID)
				}
				for previous := 0; previous < overrideIndex; previous++ {
					if logical.Overrides[previous].Enabled && overrideMatchCovers(logical.Overrides[previous], override) {
						return fmt.Errorf("logical model %s override %s: match is shadowed by broader earlier override %s",
							logical.ID, override.ID, logical.Overrides[previous].ID)
					}
				}
				enabledMatchIndexes[signature] = overrideIndex
				catchAllSeen = overrideMatchIsCatchAll(override)
			}
			switch override.Mode {
			case domain.OverrideCustomRoute:
				if override.Route == nil || len(override.Route.Steps) == 0 {
					return fmt.Errorf("logical model %s override %s: custom route required", logical.ID, override.ID)
				}
			case domain.OverrideAdjustDefault:
				if override.Route != nil {
					return fmt.Errorf("logical model %s override %s: adjust_default cannot replace route", logical.ID, override.ID)
				}
				if len(override.Prefer) == 0 && len(override.Avoid) == 0 {
					return fmt.Errorf("logical model %s override %s: adjust_default requires at least one prefer or avoid route", logical.ID, override.ID)
				}
				adjustments := map[string]string{}
				for _, group := range []struct {
					name  string
					steps []domain.RouteStep
				}{{"prefer", override.Prefer}, {"avoid", override.Avoid}} {
					for _, step := range group.steps {
						if len(step.RecoverOn) > 0 {
							return fmt.Errorf("logical model %s override %s: %s entries cannot declare recover_on", logical.ID, override.ID, group.name)
						}
						key := domain.ProviderModelKey(step.ProviderID, step.UpstreamModel)
						if !defaultSteps[key] {
							return fmt.Errorf("logical model %s override %s: %s references Provider+UpstreamModel outside default route: %s/%s",
								logical.ID, override.ID, group.name, step.ProviderID, step.UpstreamModel)
						}
						if previous := adjustments[key]; previous != "" {
							return fmt.Errorf("logical model %s override %s: Provider+UpstreamModel %s/%s appears in both or repeatedly in %s/%s",
								logical.ID, override.ID, step.ProviderID, step.UpstreamModel, previous, group.name)
						}
						adjustments[key] = group.name
					}
				}
				if len(override.Avoid) >= len(logical.DefaultRoute.Steps) {
					return fmt.Errorf("logical model %s override %s: avoid cannot remove every default route step", logical.ID, override.ID)
				}
			default:
				return fmt.Errorf("logical model %s override %s: unsupported mode %q", logical.ID, override.ID, override.Mode)
			}
			if override.Route != nil {
				if err := validateRouteSupply(logical.ID+" override "+override.ID, *override.Route, providers, supply); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

func v2StoreSecretName(ref string) string {
	for _, prefix := range []string{"store:", "env:"} {
		if strings.HasPrefix(ref, prefix) {
			return strings.TrimPrefix(ref, prefix)
		}
	}
	return ""
}

func validateOverrideMatch(modelID string, override domain.OverrideSpec) error {
	seenCallers := map[string]bool{}
	for _, rawCaller := range override.Callers {
		caller := strings.TrimSpace(rawCaller)
		if caller == "" || caller != rawCaller || seenCallers[caller] {
			return fmt.Errorf("logical model %s override %s: caller ids must be present, trimmed, and unique", modelID, override.ID)
		}
		seenCallers[caller] = true
	}
	seenProtocols := map[domain.Protocol]bool{}
	for _, protocol := range override.Protocols {
		if !domain.ValidProtocol(protocol) || seenProtocols[protocol] {
			return fmt.Errorf("logical model %s override %s: protocols must be valid and unique", modelID, override.ID)
		}
		seenProtocols[protocol] = true
	}
	seenWeekdays := map[string]bool{}
	for _, weekday := range override.Weekdays {
		weekday = strings.ToLower(strings.TrimSpace(weekday))
		switch weekday {
		case "mon", "tue", "wed", "thu", "fri", "sat", "sun":
		default:
			return fmt.Errorf("logical model %s override %s: invalid weekday %q", modelID, override.ID, weekday)
		}
		if seenWeekdays[weekday] {
			return fmt.Errorf("logical model %s override %s: weekdays must be unique", modelID, override.ID)
		}
		seenWeekdays[weekday] = true
	}
	if override.Timezone != "" {
		if _, err := time.LoadLocation(override.Timezone); err != nil {
			return fmt.Errorf("logical model %s override %s: invalid timezone %q", modelID, override.ID, override.Timezone)
		}
	}
	if override.Window != nil && (!validGraphHHMM(override.Window.Start) || !validGraphHHMM(override.Window.End) || override.Window.Start == override.Window.End) {
		return fmt.Errorf("logical model %s override %s: invalid time window %q-%q (must be non-empty)", modelID, override.ID, override.Window.Start, override.Window.End)
	}
	if override.Required.MinContext < 0 || override.Required.MinOutput < 0 {
		return fmt.Errorf("logical model %s override %s: capability minima must be non-negative", modelID, override.ID)
	}
	return nil
}

func overrideMatchIsCatchAll(override domain.OverrideSpec) bool {
	return len(override.Callers) == 0 && len(override.Protocols) == 0 && len(override.Weekdays) == 0 &&
		override.Window == nil && override.Required == (domain.Requirements{})
}

func overrideMatchSignature(override domain.OverrideSpec) string {
	type match struct {
		Callers   []string            `json:"callers,omitempty"`
		Protocols []domain.Protocol   `json:"protocols,omitempty"`
		Weekdays  []string            `json:"weekdays,omitempty"`
		Timezone  string              `json:"timezone,omitempty"`
		Window    *domain.TimeWindow  `json:"time_window,omitempty"`
		Required  domain.Requirements `json:"required_capabilities,omitempty"`
	}
	callers := append([]string(nil), override.Callers...)
	protocols := append([]domain.Protocol(nil), override.Protocols...)
	weekdays := append([]string(nil), override.Weekdays...)
	for index := range weekdays {
		weekdays[index] = strings.ToLower(strings.TrimSpace(weekdays[index]))
	}
	sort.Strings(callers)
	sort.Slice(protocols, func(i, j int) bool { return protocols[i] < protocols[j] })
	sort.Strings(weekdays)
	raw, _ := json.Marshal(match{
		Callers: callers, Protocols: protocols, Weekdays: weekdays,
		Timezone: override.Timezone, Window: override.Window, Required: override.Required,
	})
	return string(raw)
}

// overrideMatchCovers reports only relationships that can be proven from the
// constrained match language. When true, every request that could match later
// is already consumed by earlier because Override evaluation is first-match.
func overrideMatchCovers(earlier, later domain.OverrideSpec) bool {
	containsAllStrings := func(broader, narrower []string, fold bool) bool {
		if len(broader) == 0 {
			return true
		}
		if len(narrower) == 0 {
			return false
		}
		set := make(map[string]bool, len(broader))
		for _, value := range broader {
			if fold {
				value = strings.ToLower(strings.TrimSpace(value))
			}
			set[value] = true
		}
		for _, value := range narrower {
			if fold {
				value = strings.ToLower(strings.TrimSpace(value))
			}
			if !set[value] {
				return false
			}
		}
		return true
	}
	protocolStrings := func(values []domain.Protocol) []string {
		out := make([]string, len(values))
		for index := range values {
			out[index] = string(values[index])
		}
		return out
	}
	if !containsAllStrings(earlier.Callers, later.Callers, false) ||
		!containsAllStrings(protocolStrings(earlier.Protocols), protocolStrings(later.Protocols), false) ||
		!containsAllStrings(earlier.Weekdays, later.Weekdays, true) {
		return false
	}
	earlierTemporal := earlier.Window != nil || len(earlier.Weekdays) > 0
	if earlierTemporal && earlier.Timezone != later.Timezone {
		return false
	}
	if !overrideWindowCovers(earlier.Window, later.Window) {
		return false
	}
	a, b := earlier.Required, later.Required
	if (a.Text && !b.Text) || (a.Images && !b.Images) || (a.Stream && !b.Stream) ||
		(a.Tools && !b.Tools) || (a.ParallelTools && !b.ParallelTools) ||
		(a.Reasoning && !b.Reasoning) || (a.StructuredOutput && !b.StructuredOutput) ||
		(a.Vision && !b.Vision) || a.MinContext > b.MinContext || a.MinOutput > b.MinOutput {
		return false
	}
	return true
}

func overrideWindowCovers(earlier, later *domain.TimeWindow) bool {
	if earlier == nil {
		return true
	}
	if later == nil {
		return false
	}
	for minute := 0; minute < 24*60; minute++ {
		if legacyWindowMatchesMinute(*later, minute) && !legacyWindowMatchesMinute(*earlier, minute) {
			return false
		}
	}
	return true
}

func normalizeFinalV2RouteRecovery(route *domain.RouteSpec) {
	if route == nil || len(route.Steps) == 0 {
		return
	}
	final := &route.Steps[len(route.Steps)-1]
	for _, failure := range final.RecoverOn {
		if !failure.Valid() {
			return
		}
	}
	final.RecoverOn = nil
}

func validateRouteSupply(owner string, route domain.RouteSpec, providers map[string]*domain.Provider, supply map[string]bool) error {
	seen := map[string]bool{}
	for index, step := range route.Steps {
		if providers[step.ProviderID] == nil {
			return fmt.Errorf("%s route step %d: unknown provider %q", owner, index+1, step.ProviderID)
		}
		if !supply[domain.ProviderModelKey(step.ProviderID, step.UpstreamModel)] {
			return fmt.Errorf("%s route step %d: provider %s does not supply upstream model %q",
				owner, index+1, step.ProviderID, step.UpstreamModel)
		}
		key := domain.ProviderModelKey(step.ProviderID, step.UpstreamModel)
		if seen[key] {
			return fmt.Errorf("%s route step %d: duplicate Provider+UpstreamModel", owner, index+1)
		}
		seen[key] = true
		seenFailures := map[domain.FailureType]bool{}
		for _, failure := range step.RecoverOn {
			if !failure.Valid() {
				return fmt.Errorf("%s route step %d: unknown recover_on failure %q", owner, index+1, failure)
			}
			if seenFailures[failure] {
				return fmt.Errorf("%s route step %d: recover_on values must be unique", owner, index+1)
			}
			seenFailures[failure] = true
			if index < len(route.Steps)-1 && !domain.FallbackAllowed(failure) {
				return fmt.Errorf("%s route step %d: fallback on %q is not allowed", owner, index+1, failure)
			}
		}
	}
	return nil
}

func (f *File) addV2ModelIssue(logicalModelID, kind, objectID, message string, blocking bool) {
	f.V2MigrationIssues = append(f.V2MigrationIssues, domain.LegacyMappingIssue{
		LogicalModelID: logicalModelID,
		Kind:           kind, ObjectID: objectID, Message: message, Blocking: blocking,
	})
}

func providerTypeFromChannel(channelType domain.ChannelType) domain.ProviderType {
	if channelType == domain.ChannelCliproxyCodex {
		return domain.ProviderCliproxyCodex
	}
	return domain.ProviderCustom
}

func legacyTargetProviderID(targetID domain.ResourceTargetID) string {
	return "target-" + string(targetID)
}

func requirementsFromNames(names []string) domain.Requirements {
	var required domain.Requirements
	for _, name := range names {
		domain.SetRequirementCapability(&required, name, true)
	}
	return required
}
